"""
Pages Batch 45 (Canvases 256-260, pp. 218-222) for Wellcome MS.244.
Covers five pages of the Main Compendium (Medical & Surgical Receipts):
  - Canvas 256 (p. 218 / ccxviij): Stone & Strangury (Makeome/Wahodyne Miles, Mr Davell, 'An Exelent water for the Stone and collirke', Latin remedies & syrups)
  - Canvas 257 (p. 219 / ccxix): Stone & Colic (cow's milk & saxifrage waters, wagtail powder, oak-leaf distillate, radish & horehound remedies, bean-stalk ashes)
  - Canvas 258 (p. 220 / ccxx): Stone & Calculus (Lapis / Calculum; pimpernel & castor enema, grandmother Elizabeth's receipts, Mr Cafill, Lady L., 1631 July note)
  - Canvas 259 (p. 221 / ccxxj): Stone, Colic & Iliaca (Dr. John Sadler's eggshell powder, tobacco-smoke clyster experiment & King Henry VIII servant anecdote, Dr. Turner on umbilical cord, laxative ointments)
  - Canvas 260 (p. 222 / ccxxij): Collica & Illiaca (Thomas Cynes's alexipharmacon, wolf-skin girdle, dried grasshoppers, roasted onion plaster, earthworm powder, cross-ref to p. 218)
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


